mapper.update:
UPDATE warn_event
SET hazard_event_id = #{hazardEventId}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT tunnel_id AS tunnelId, warn_level AS level, hazard_type AS hazardType, COUNT(*) AS cnt FROM warn_event WHERE create_time >= #{from} AND create_time < #{to} AND 1=0
AND ${scope.column} IN #{p}
GROUP BY tunnel_id, warn_level, hazard_type
